export const CHALLENGES_BY_LANG: Record<Lang, string[]> = {
  en: CHALLENGES,
  de: CHALLENGES_DE,
  es: CHALLENGES_ES,
  fr: CHALLENGES_FR,
  ru: CHALLENGES_RU,
};

export const TEAMMATE_BY_LANG: Record<Lang, string[]> = {
  en: TEAMMATE_CHALLENGES,
  de: TEAMMATE_DE,
  es: TEAMMATE_ES,
  fr: TEAMMATE_FR,
  ru: TEAMMATE_RU,
};

/**
 * The default challenge pool for a team size and language. Two-player teams
 * get the base pool plus the teammate-only challenges, in the given language.
 */
export function defaultChallengePool(teamSize: number, lang: Lang = "en"): string[] {
  const base = CHALLENGES_BY_LANG[lang] ?? CHALLENGES;
  const team = TEAMMATE_BY_LANG[lang] ?? TEAMMATE_CHALLENGES;
  return teamSize >= 2 ? [...base, ...team] : [...base];
}
